INSERT INTO video_impl_claims VALUES(125,'gaZwLEsP4wY','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','전술 구조 설명은 풍부하나 FC 역할·포커스·팀 설정 어휘로 옮길 수 있는 명시 주장이 없다. 쿠마스 평가는 obs#819의 기존 판정을 재확인할 뿐 새 값 주장이 아니다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(126,'4Zly8FIdpr4','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','상대 관점 서술이며 리버풀 측 FC 역할·포커스·팀 설정에 대한 명시 주장이 없다. 압박 인원 6명 서술은 obs#818 재확인이지 새 설정값 주장이 아니다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(127,'mZYZ5LVPtDA','instruction',86,NULL,NULL,NULL,'width','우측 터치라인 폭 유지(기본 위치)','「he stretches the opposition defense immediately just with his starting point as he forces the fullback to break away from a narrow defensive shape」(시작 위치만으로 상대 수비를 즉시 벌리고, 풀백이 좁은 수비 형태에서 떨어져 나오게 만든다)','APPLIED','D+1 PENDING(1874 단독)에서 승격 — 독립 4소스(1874·Talk Villa·Tanswell 현장·프랑스어 매체)가 「우측 폭」으로 일치하고, 실측 툴x 72.4(맥긴 67.8보다 바깥, 터치라인 85는 아님)는 Tanswell이 관찰한 맥긴·완비사카와의 설계된 자리바꿈으로 설명된다 — 즉 기본은 폭, 평균이 안쪽인 것은 로테이션의 결과다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM-HIGH — auto-caption. 단일 경기·하부 리그 상대.','2026-09-18');
INSERT INTO video_impl_claims VALUES(128,'mZYZ5LVPtDA','instruction',86,NULL,NULL,NULL,'in_behind_runs','우측 채널 배후 침투(지시)','「There''s the space. That''s where it''s going to open up. I want you to attack it and make those runs in behind to give us a threat down the right channel」(저기가 공간이다. 저기가 열릴 곳이다. 저길 공략해 배후로 뛰어서 우측 채널에 위협을 만들어라)','HELD','화자가 에메리의 말을 재구성한 것이지 전사된 지시가 아니다(정지화면 해설). 방향은 Tanswell의 「배후를 상시 위협하는 우측 윙어가 이번 여름 최우선 과제였다」와 정합. 재판정 조건: 스퍼스 원정 이후 음바예의 배후 스루패스 수신 이벤트.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 인용은 화자의 재구성.','2026-09-18');
INSERT INTO video_impl_claims VALUES(129,'mZYZ5LVPtDA','limit',86,NULL,NULL,NULL,'defensive_work','원정 수비 임무 수행 — 첫 긍정 관찰','「I thought he put in some seriously hard yards to track his man and do the defensive part of his work as well… is that part of the process of he''s new here, he wants to impress」(자기 매치업을 따라가며 상당히 힘든 거리를 뛰었고 수비 몫도 해냈다 — 다만 새로 왔고 인상을 남기려는 과정의 일부인가)','HELD','⚠️ 반쪽만 맞다 — 「수비 몫도 해냈다」는 카운팅 스탯(태클 0·인터셉트 0)과 비점유 높이 63.3이 반대 방향이다. 다만 **대인 추적 주행**은 우리 데이터에 없다(이벤트 기반이라 오프더볼 거리를 못 센다). 재판정 조건: 다음 우측 배치 경기에서 비점유 전진도가 55 이하로 내려오거나 태클·인터셉트가 발생하면 APPLIED로 올린다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','LOW-MEDIUM — auto-caption · 단일 소스 · 하부 리그 상대.','2026-09-18');
INSERT INTO video_impl_claims VALUES(130,'p7YDUThRRXQ','role',10,NULL,'cam_halfwinger',NULL,NULL,NULL,'「he has the freedom to go out onto that right side from the central areas and Mbaye particularly has that intelligence to cut inside and dovetail with him」(중앙에서 우측으로 나갈 자유가 있고, 음바예는 안쪽으로 접어 그와 맞물린다)','APPLIED','커널이 cam_halfwinger/Roaming .502를 내면서 Δ0.012 무결정이었던 구간 중 **역할 축**을 서사가 닫는다 — 「중앙 배치 + 우측으로 드리프트」는 halfwinger의 정의 그대로이고, Tanswell 현장 관찰(「McGinn drifting over to the inside channel and overloading the right side with Mbaye, sometimes swapping positions」 맥긴이 안쪽 채널로 흘러 음바예와 우측을 과부하시켰고 때로 자리를 맞바꿨다)이 독립 2소스를 만든다. ⚠️ **포커스 축(Roaming↔Attack)은 여전히 무결정**으로 남긴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM-HIGH — 독립 2소스(팬채널 auto-caption + 현장 기자 실시간 기록)가 커널 역할값과 일치.','2026-09-18');
INSERT INTO video_impl_claims VALUES(131,'p7YDUThRRXQ','role',178,NULL,'cb_bpd',NULL,NULL,NULL,'「he''s from that old school of centre halves… but what he''s also got is that ability to put his foot on the ball and pass into midfield」(구식 센터백 계보이지만, 발로 잡고 미드필드로 찔러주는 능력까지 있다)','HELD','슬롯 정본 cb_bpd/Build-Up과 방향 정합이고 D+1의 「파우 토레스와 같은 지역, 조금 더 띄운다」와도 겹친다. 그러나 **빌라 공식전 1경기·하부 리그 상대**라 승격하지 않는다. 재판정 조건: 스퍼스 원정 이후 프리미어리그 2경기 표본.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 표본 1경기.','2026-09-18');
INSERT INTO video_impl_claims VALUES(132,'p7YDUThRRXQ','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(133,'WajH4NOz_D0','limit',11,NULL,NULL,NULL,'progression','피벗 진취성 결여(수동성)','「I watched it back again today and… he''s even worse again on the second viewing… He was incredibly passive」(오늘 다시 돌려봤는데 두 번째 시청에서 더 나빴다… 극도로 수동적이었다)','HELD','D+1 미해결 충돌 1번을 닫지는 않되 **성격을 특정**한다 — 실측은 duels_won 11·tackles 3·패스 47/51(92%)로 **행동량**이 높고, 서사가 때리는 것은 **전진·주도**의 부재다(avg_x 40.1로 피벗 최전방 바클리 49.77보다 −9.7, 진영 최후방 피벗). 두 층이 서로 다른 것을 재고 있으므로 SofaScore 7.4와 서사 평점 4~5는 모순이 아니다. 재판정 조건: 고메스 복귀 후 같은 슬롯의 전진패스·프로그레시브 캐리 대조.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 재시청 기반 단일 화자. 실측과의 층 분리는 우리 판정.','2026-09-18');
INSERT INTO video_impl_claims VALUES(134,'WajH4NOz_D0','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(135,'fKDbTccRjGk','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(136,'At5v2hKj1vI','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(137,'Jp52xd-xLt8','instruction',NULL,'AVL',NULL,NULL,'away_vs_top_game_plan','defend_deep_then_transition','원문 「we knew before the match, we needed defense and we needed to be so so resilient defensively. We needed the keeper saving us.」(경기 전부터 우리는 알고 있었다 — 수비가 필요하고 수비적으로 대단히 견뎌야 한다는 것을. 골키퍼가 우리를 구해줘야 했다.) — auto-caption','APPLIED','실측이 전면 지지한다: def_x 30.6(26/27 최저, optimal:vs-strong 라인 43보다 낮다) · PPDA 13.24 · 상대 진영 패스 102회 · 3골 전부 오픈플레이(세트피스 xG 0.00) · fast-break 슈팅 3회. match_game_setups(report 47)에 Counter/Balanced/라인 48로 이미 기록했다. 시즌 정본은 바꾸지 않는다(단일 경기).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(138,'k6dbBj7Tz7w','instruction',NULL,'AVL',NULL,NULL,'defensive_shape_second_half','back_five_right_side_shift','원문 「sometimes with back four is not enough to defend completely the … side of the field … the second half we needed more with John McGinn」(때로는 백4로는 측면을 완전히 수비하기에 충분하지 않다 … 후반에는 존 맥긴으로 더 필요했다.) — auto-caption','APPLIED','실측이 독립 확인한다 — 맥긴 수비액션 x 전반 56.3 → 후반 32.1, y 32.8 → 18.2. 후반 57′·58′·77′ 수비액션이 x 11.8~16.2로 백4 라인 깊이이고 전반에는 그 대역이 0건이다. 단 좌측은 부엔디아가 반대로 35.6 → 47.6으로 올라가 대칭 5-3-2가 아니라 **우측 편중 백5**다. 리포트 §2·§6에 이 형태로 기록하고 manager_profiles.formation의 「5-3-2 전환 미관측」 서술을 정정 대상으로 올린다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(139,'k6dbBj7Tz7w','instruction',NULL,'AVL',NULL,NULL,'buildup_back_three_source','pivot_drop_kamara','원문 「someday we are the first half we use it more [Kamara] dropping dropping」(어떤 날은 전반처럼 카마라를 더 내려서 쓴다.) — auto-caption, Kamara가 「camera」로 오인식','REJECTED',unistr('[2026-09-20 D+1 재판정] **REJECTED** — D+0가 건 조건(전반 카마라 보유 x vs CB 라인 x, Δ≤8이면 APPLIED)을 WhoScored matchId=1983589 재수집(period·minute 포함)으로 집행했다. 전반 카마라 41.3(n=37) vs CB 라인 30.2(n=50) → **Δ=11.1**로 임계 밖. 자기 진영(x<50)만 봐도 Δ=8.8. ⭐ 단 좌우로는 두 CB 사이(y 43.0 / 32.5·70.7)이고 전반 보유의 19%가 CB 라인 깊이 이하여서 **행동은 존재하나 상시 구조가 아니다** — 회견 원문의 「someday」와 정합적이다. obs#866. ⛔ 빌드업 축·슬롯 정본은 변경하지 않는다(단일 경기, 기각 방향). ‖ [2026-09-20 D+1 재-재판정] ⛔ **REJECTED를 철회하고 HELD로 되돌린다 — D+0이 건 임계 자체가 잘못 설계됐다.** 「전반 보유 전체의 평균 x 격차 ≤8」은 **국면 한정 행동을 평균으로 검정하는 오류**다. 빌드업 국면에서만 내려오는 선수는 전반 전체 평균으로는 절대 CB 라인에 닿지 않는다(희석). ⭐ 계기: Jacob Tanswell(The Athletic) 2026-09-20 정식 기사 본문이 이 행동을 **국면·시점 한정으로 명시**했다 — 원문 「A quarter of an hour into the match, **when Villa built from the back**, Manzambi dropped deep, occasionally alongside Joao Gomes, as **Boubacar Kamara moved into a back three**.」(경기 15분 무렵 **빌라가 후방 빌드업을 할 때** 만잠비가 깊게 내려왔고 때때로 주앙 고메스 옆에 섰으며, **카마라는 백3로 이동했다**.) — 1티어 기자 서면. 우리 실측도 같은 것을 보고 있었다: 전반 보유 37건 중 **7건(19%)이 CB 라인 깊이 이하**이고 그중 6건이 두 CB 사이였다(obs#866). ⇒ **새 재판정 조건**: 골킥·자기 진영 시작 시퀀스만 추려 **빌드업 국면 한정**으로 카마라 x와 CB 라인 x를 대조한다(평균 전체 비교 금지). 격차가 8 이하면 APPLIED. ⛔ 그 전까지 빌드업 축·슬롯 정본은 불변.\u000a\u000a[2026-09-21 D+2 재판정] **REJECTED(확정)** — D+1이 건 「빌드업 국면 한정」 조건을 집행했다. WhoScored matchId=1983589를 pulled=2026-09-21 scope=full로 재수집(1,627건)해 골킥·자기 진영(x<40) 시작 시퀀스만 추려 대조했다(core.whoscored). 전반 빌드업(시퀀스 41·이벤트 145): 카마라 x=33.9(n=20) vs CB라인 23.3(n=35) → **Δ=10.6 > 8**. Tanswell 시점 한정(전반 10~30′): Δ=11.4. 골킥 시퀀스 한정: Δ=16.0. 전경기 빌드업: Δ=11.1. ⇒ 국면을 좁혀도 임계를 넘지 못한다 — D+1의 임계 재설계는 정당했으나 결론은 바뀌지 않았다. ⭐ **기각 범위 한정**: 시퀀스 단위로는 카마라·CB 동시 관여 13개 중 **4개(31%)가 Δ≤8**이고 전부 전반 1′·5′·14′·30′에 몰린다(36′ 이후 0개). Tanswell의 「경기 15분 무렵 … 때때로」라는 시점·빈도 서술은 참이고, **「백3」를 빌드업의 기본 형태로 읽는 것만 거짓**이다. ⛔ 부가 주장도 기각: 「만잠비가 깊게 내려와 고메스 옆에 섰다」 — 빌드업 국면 만잠비 x=51.0 vs 고메스 37.9로 **13 더 높고**, 전반 내내 올라갔다(0~15′ 54.0 → 15~30′ 58.7 → 30~53′ 63.0). 좌우도 y 43.6 vs 70.3으로 다른 레인이다. ⚠️ 한계: 온더볼 관여 깊이만 본다(터치 없는 위치 점유는 이벤트에 없다). 게임 설정은 바꾸지 않는다. obs#920.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(140,'kJZ0G7WvLWY','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Counter','원문 「this season Aston Villa are playing 86% more long balls than last season, and we spoke in many many meetings yesterday and two days ago」(올 시즌 아스톤 빌라는 지난 시즌보다 롱볼을 86% 더 많이 하고 있어서, 어제와 이틀 전 수많은 미팅에서 그 얘기를 했다.) — auto-caption','APPLIED','상대 감독의 **정량 사전 스카우팅**이 우리 buildup 축 갱신(25/26 Short Passing → 26/27 상대 의존 고다이렉트)을 독립 확인했다. 이 경기 실측 롱볼 14.5%는 26/27 최고이고 core.team_settings.suggest도 Counter를 제안해 match_game_setups(report 47)에 Counter로 기록했다. ⛔ 시즌 정본 team_tactic_setups(Short Passing)는 바꾸지 않는다 — 에메리의 빌드업은 상대 의존이고 헐전 롱볼 5.6%가 같은 시즌에 있다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(141,'kJZ0G7WvLWY','instruction',NULL,'AVL',NULL,NULL,'gk_long_kick_route','goal_kick_to_ten_flick_to_nine','원문 「we conceded one unacceptable goal from long goal kick with a long ball」(우리는 롱 골킥에서 롱볼로 용납할 수 없는 골을 하나 내줬다.) — auto-caption','APPLIED',unistr('67′ 잭슨 골(xG 0.060)의 경로를 상대 감독이 직접 특정했다. 스즈키 패스 38회 중 성공 22(58%)·롱킥 비중이 이 루트의 실측 근거이고, 브뤼헤전에서 정식화한 「맨투맨 하이프레스 → 의도적 GK 백패스 → 스즈키 롱킥」의 3번째 표본이자 **첫 득점 전환**이다. 상대가 사전에 대비했는데도 성립했다는 점이 추가 정보다.\u000a\u000a[2026-09-21 D+2 확증] ⭐⭐ **Opta 이벤트로 경로 전체가 복원됐다.** 66′08 스즈키 Pass(qualifiers **Longball + GoalKick**, x4.9) → 66′11 잭슨 BallTouch(x67.2) → 66′12 만잠비 Pass(**IntentionalGoalAssist + KeyPass**) → 66′14 잭슨 TakeOn 성공(반더벤 Challenge 실패) → 66′16 잭슨 Goal(**Volley**, BoxCentre). ⇒ 「골킥 → 9번 플릭 → 10번 → 9번 마무리」가 이벤트 단위로 확정된다. ⭐ **감독 1차 진술이 붙었다**(일본어 경유): 「ビルドアップではロングボールを選択することもできる … 実際今日の我々の2点目でもそれをやってくれた」(빌드업에서 롱볼을 선택할 수도 있다 … 실제로 오늘 우리 두 번째 골에서도 그것을 해줬다). 일본 매체 FOOTBALL ZONE이 같은 시퀀스를 독립 서술했고, 데 제르비도 「we conceded one unacceptable goal from long goal kick」(롱 골킥에서 받아들일 수 없는 실점을 했다)으로 상대편에서 확인했다. ⭐ 이 확증은 claim #144(GK=11번째 필드플레이어) **기각과 모순되지 않는다** — 스즈키의 골킥 7회는 전부 롱이었고(숏 0회), 그 롱킥 중 1회가 득점으로 전환됐다. GK는 빌드업 **참여자**가 아니라 **발사대**이며 그 발사대가 생산적이었다는 뜻이다.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(142,'BTW1C1UCPN0','instruction',NULL,'AVL',NULL,NULL,'concession_second_ball_clear','second_clear_fail_ruggeri_buendia','원문 「We have one opportunity to deal with it here. Rejieri, clear it. We then have another opportunity here. Buendía, win the ball. Clear it. We don''t.」(여기서 처리할 기회가 한 번 있었다. 루헤리, 걷어내라. 여기서 또 한 번 기회가 있었다. 부엔디아, 볼을 따내라. 걷어내라. 우리는 못 했다.) — auto-caption, Rejieri=Ruggeri','APPLIED',unistr('⭐ **Opta 이벤트 시퀀스가 이 서술을 그대로 확인한다.** 86′(Opta 85′) 장면: 루헤리 Aerial → 루헤리 Interception ×2 → 밍스 Clearance(x 13.8) → **루헤리 BallRecovery(x 21.7) → 루헤리 Dispossessed(쿠두스 Tackle)** → 루헤리 BlockedPass → **부엔디아 TakeOn 실패**(그레이 Tackle) → 쿠두스 BallRecovery → 쿠두스 → 마르무시 → 쿠두스 어시스트 → 갤러거 Goal. 즉 실점 원인은 블록 구조 붕괴가 아니라 **자기 진영 2차 볼 처리 2회 연속 실패**다. ⇒ 게임 구현 함의는 라인/수비접근 축이 아니라 **세컨볼 대응**이며, 이번 회차에 팀 설정은 바꾸지 않는다.\u000a\u000a[2026-09-21 D+2 재검증] **APPLIED 유지 — 새 스냅샷에서 시퀀스가 소수점까지 재현된다.** pulled=2026-09-21 scope=full로 다시 받아 84′00~85′46 전 구간을 펼쳤고 D+1이 적은 고리가 그대로 나온다: 85′21 루헤리 Aerial → Interception ×2(85′21·85′31) → 85′35 **밍스 Clearance(Head, x13.8)** → 85′37 **루헤리 BallRecovery(x21.7)** → 85′38 **루헤리 Dispossessed(쿠두스 Tackle)** → 85′39 루헤리 BlockedPass → 85′40 **부엔디아 TakeOn 실패(그레이 Tackle)** → 쿠두스 BallRecovery → 쿠두스 → 마르무시 → 쿠두스(IntentionalAssist·BigChanceCreated) → 85′46 갤러거 Goal. ⭐ **D+2 스윕의 반대 해석을 기각한다**: 라이브블로그 4종이 86′ 실점 경위에 루헤리를 지목하지 않았다는 이유로 「Townley 단독 주장 · 교차검증 실패」로 낮추자는 판단이 있었으나, **Opta가 루헤리의 Dispossessed를 직접 기록**하고 있다. ⇒ 라이브블로그의 침묵은 반대 증거가 아니다(실시간 기록은 실점 경위를 선수 단위로 적지 않는다). ⛔ 단 **최종 상실은 부엔디아의 TakeOn 실패**이고 루헤리의 Dispossessed는 그 앞 고리다 — value가 두 이름을 모두 담고 있는 것이 정확하다. ⚠️ 사족 정정: TNT의 「매티 캐시의 굴절」은 이 스냅샷에도 없다(obs#871 유지). 다만 NBC 라이브가 같은 굴절을 적었다 — 굴절은 Opta 이벤트로 남지 않는 종류라 **미검증으로 유지**하고 DB에 반영하지 않는다.'),'reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(143,'BTW1C1UCPN0','instruction',NULL,'AVL',NULL,NULL,'set_piece_defending_marking','mark_drop_under_flight_fail','원문 「blockers and grabbers that are grabbing our players that are stopping us when this ball goes to Van Heeka」(우리 선수를 붙잡아 판 헤케에게 볼이 갈 때 우리가 못 가게 막는 블로커·그래버) · 「three players for Villa here who are beyond Ming」(밍스보다 뒤에 있는 빌라 선수가 셋이다) — auto-caption, Van Heeka=van Hecke · Ming=Mings','APPLIED',unistr('⛔ **재판정 조건**: 세트피스의 개인 마킹 배치는 우리 이벤트 데이터로 특정되지 않는다(리포트 「레퍼런스·한계」에 이미 명시). 현재 근거는 **영상 프레임 1소스**뿐이다. ⇒ 다음 회차에 ⑴ 독립 2번째 프레임 소스(다른 채널·기사) ⑵ 또는 세트피스 실점 2경기째 누적 중 하나가 생기면 재판정한다. 정황 지지: 코너 1-11 · 상대 세트피스 xG 0.57 vs 우리 0.00 · 1874의 「세트피스 양방향 비대칭」 서술. ⚠️ 별건 가설(인과 아님): 세트피스 코치 오스틴 맥피가 2026-07 첼시로 이적했고 25/26 빌라는 세트피스 득점 유럽 공동 1위였다 — **이번 경기를 맥피 부재와 연결한 분석은 0건**이므로 시즌 누적 추적 대상으로만 남긴다.\u000a\u000a[2026-09-21 D+2 재판정] **APPLIED** — 재판정 조건 ⑴(독립 2번째 소스)이 충족됐고 실측이 메커니즘을 확인했다. The Holy Trinity Show(dgEOoi6Pdrc, 2026-09-21)가 「a pretty simple straight set piece that just **cleared the head of Tyrone Mings** … that was the **first set piece goal we''ve conceded in the Premier League this season**」(밍스의 머리를 넘긴 아주 단순한 세트피스 … 이번 시즌 PL 첫 세트피스 실점이었다)로 독립 서술했다. ⭐ Opta가 구조를 확정한다: **97′28 반헤케 Goal quals = Head + BoxCentre + SetPiece + FirstTouch + BigChance**, 어시스트는 **로버트슨의 Cross + FreekickTaken + SetPiece**(코너가 아니라 **프리킥**이다 — D+0의 코너 정황 서술은 이 골에 해당하지 않는다). ⇒ 「세트피스 크로스가 박스 중앙 공중 경합을 이기고 헤더로 마무리됐다」까지 확정. ⛔ **잔여 한계를 남긴다**: 개인 마킹 배치(누가 누구를 놓쳤는가)는 여전히 우리 이벤트 데이터로 특정되지 않는다 — 「밍스의 머리를 넘었다」는 영상 서술 1소스다. **이 해상도까지만 APPLIED**이고 마킹 지시 축의 처방 변경 근거로는 쓰지 않는다. ⚠️ 별건 가설(인과 아님) 유지: 세트피스 코치 오스틴 맥피의 2026-07 첼시 이적.'),'reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(144,'BTW1C1UCPN0','instruction',NULL,'AVL',NULL,NULL,'gk_role_in_buildup','gk_as_eleventh_outfield','원문 「Most teams go ''we''ve got 10 outfield players and a goalkeeper.'' Aston Villa have got 11 outfield players.」(대부분의 팀은 「필드 플레이어 10명과 골키퍼 1명이 있다」고 한다. 아스톤 빌라는 필드 플레이어가 11명이다.) — auto-caption','REJECTED',unistr('⛔ **재판정 조건**: 근거로 제시된 수치(론치 성공률 47% · 골킥 9회 · 패스 32회 정확도 72% 중 롱 15)가 **우리 실측에 없는 축**이다. 우리 값은 스즈키 패스 38회·성공 22(58%)로 **패스 총계부터 어긋난다**(제공사 차이 가능). ⇒ FotMob·SofaScore에서 GK 골킥 숏/롱 분해를 같은 스냅샷으로 받아 대조한 뒤 판정한다. 방향 자체는 obs#864(롱볼 26/27 증가)·claim #141(GK 롱킥 루트 득점 전환)과 정합해 기각 후보는 아니다.\u000a\u000a[2026-09-21 D+2 재판정] **REJECTED** — D+1이 건 조건(골킥 숏/롱 분해를 같은 스냅샷으로 대조)을 두 제공사로 집행했다. **Opta: 골킥 7회 · 롱 7 · 숏 0 · 성공 3(43%)**. 숏 골킥이 한 번도 없다 — 「11번째 필드 플레이어」의 핵심 행동이 0회다. 스즈키 패스 43 중 롱 27(성공 10·37%) · 숏 16(성공 16·100%)이나 그 숏은 **오픈플레이 자기 진영**이지 재시작이 아니다. SofaScore(pulled 2026-09-21): 패스 38 · 롱볼 26(정확 9·35%) · 자기진영 14/15 vs 상대진영 7/23. ⇒ 빌드업에서 GK는 참여자가 아니라 **발사대**다. claim #141(GK 롱킥 루트 → 67′ 득점, APPLIED)·obs#864와 같은 방향이므로 방향 자체를 뒤집는 기각이 아니라 **역할 명명의 기각**이다. ⭐ 근거 수치 자체도 무효: UTV의 「골킥 9 · 론치 성공률 47% · 패스 32 중 롱 15」는 Opta·SofaScore 어느 쪽으로도 재현되지 않는 반면 **두 제공사는 서로 수렴한다**(롱볼 27/26 · 37%/35%) — 제공사 차이가 아니라 출처 미상이다. obs#923. ⛔ 단 스위퍼·세컨볼 관여는 별개로 실재한다(KeeperSweeper 1/1 · BallRecovery 12 · 볼캐리 9회 52m) — 이 기각은 `gk_role_in_buildup` 축에 한정된다. obs#922.'),'reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(145,'kj4gz1QXrl8','instruction',NULL,'AVL',NULL,NULL,'halftime_left_side_cover','winger_tucks_to_support_lb','원문 「tactical tweak at halftime that Emry got going on that left side with Wendia helping out a lot more and I think it allowed Roger to be more free」(에메리가 하프타임에 좌측에서 부엔디아가 훨씬 더 많이 커버하도록 전술을 손봤고, 그것이 루헤리를 더 자유롭게 만들었다고 본다.) — auto-caption, Wendia=Buendía · Roger=Ruggeri','APPLIED','⭐ 실측이 방향을 지지한다. 부엔디아 수비액션: **전반 9건 → 후반 16건**으로 늘었고, 깊이는 전반 20′~HT **x평균 54.1 → 후반 42.7**로 내려왔다. 전반 0~20′ 구간만 24.1로 낮은데 이는 **사비뉴 상대 좌측 과부하**(Bains·Tanswell 서술)와 정합한다 — 즉 전반 초반 강요된 하강 → 20′ 이후 반등 → HT 조정으로 안정적 커버. ⇒ 게임 구현 함의: 좌측 와이드의 Support 성향(수비 가담) 유지 근거. ⛔ 단일 경기이므로 슬롯 정본은 변경하지 않는다.','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(146,'ahxMgX0BH2c','none',NULL,'AVL',NULL,NULL,NULL,NULL,'구현 축 주장 없음 — 선수 평가·주심 판정·세트피스 체감 서사 중심이다.','NA','axis=none. 완비사카 HT 교체 관련 평가와 세트피스 양방향 비대칭 관찰은 observations로 옮겼다(구현 축 주장이 아니라 관찰·평가이므로).','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(147,'yn-UvcWhAio','none',NULL,'AVL',NULL,NULL,NULL,NULL,'구현 축 주장 없음 — 선수 본인 경기 후 인터뷰(득점 장면 설명·적응 서사).','NA','axis=none. ⭐ 득점 장면 본인 설명이 우리 어시스트 기록(카마라)과 정합함을 확인했다. ⚠️ 72′ 교체·전반 치료 질문은 인터뷰에 0건. ※ axis=none 규약상 대상 칼럼은 비운다 — 만잠비 귀속 내용은 player_duties·observations로 옮겼다(G17).','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(148,'noampLJzxn0','instruction',NULL,'AVL',NULL,NULL,'defensive_shape_first_half','mid_block_to_532_at_20min','원문 「it almost seemed like Aston Villa at times were defending in a 5-3-2」(빌라가 때때로 5-3-2로 수비하는 것처럼 보였다) · 「first 20, 25 minutes where Tottenham were the better side」(토트넘이 더 나았던 첫 20~25분) — auto-caption, 전환 시점을 **전반**에 둔다','REJECTED','⛔ **실측 기각.** 맥긴 수비액션 x: 전반 0~20′ **55.7**(n=1) · 전반 20′~HT **58.4**(n=2, 41.9·74.9) · 후반 **32.1**(n=8, 최저 11.8·14.1·16.2). 전반에는 백라인 깊이(x<20) 수비액션이 **0건**이고 20′ 이후에도 하강 신호가 없다 — 오히려 평균이 올라간다. 반면 상대팀 채널 The Tottenham Blueprint는 같은 현상을 **명시적으로 「in the second half」**라 했고 우리 실측과 일치한다. ⇒ Bains의 시점 서술은 기각하고 **후반 전환(§2·claim #138) 정본을 유지**한다. ⭐ 단 Bains가 관찰한 「전반 좌측 고전」 자체는 실측과 맞는다(부엔디아 전반 0~20′ 수비액션 x 24.1) — **틀린 것은 시점과 형태 귀속이지 관찰이 아니다.**','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(149,'FP7obsFLxRQ','none',NULL,'AVL',NULL,NULL,NULL,NULL,'구현 축 주장 없음 — 「빌라가 더 나은 GK와 더 나은 9번을 가졌다」는 선수 질 비교 논지.','NA','axis=none. 채널 미상(oEmbed Unauthorized). 구조·국면 서술이 없어 구현 재료로 쓰지 않는다.','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(150,'XRJgUjer1cc','instruction',NULL,'AVL',NULL,NULL,'defensive_shape_second_half','back_five_right_side_shift','원문 「in the second half … They started bringing their midfield very deep to protect the sides … McGinn was dropping in on the right as well to protect us against Marmoush.」(후반에 … 측면을 보호하려고 미드필드를 아주 깊이 내리기 시작했다 … 맥긴도 우측으로 내려앉아 마르무시에 대비했다.) — auto-caption, **상대팀 채널**','APPLIED','⭐⭐ **상대팀 관찰자의 독립 확인**이다(claim #138은 감독 자인 + 우리 실측이었고, 여기에 제3자 축이 붙었다). 추가 실측 보강 1건: **우측 풀백의 깊이가 교체로 더 내려갔다** — 완비사카 전반 수비액션 x평균 **33.1**(n=6) → 캐시 후반 **17.2**(n=7, 5.6·8.1·8.5·9.2·16.0). 즉 후반 우측은 맥긴 하강(56.3→32.1)과 풀백 하강(33.1→17.2)이 겹친 **이중 하강**이다. ⚠️ 출처 성격: 이 영상은 이 경기 전용 분석이 아니라 시즌 리뷰 포맷이며 해당 구간만 이 경기를 다룬다. 3티어 팬 채널·auto-caption.','reports/match-watch/2026-09-19-avl-tottenham.md D+1 절 · 전사 직접 독해 · WhoScored matchCentreData matchId=1983589 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반 주장. 판정은 Opta 이벤트 재집계(core.whoscored)로 했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(151,'7J0YLBV25vc','instruction',NULL,'CHE',NULL,NULL,'back_three_reason','double_mark_opposing_nine','원문 「The way Chelsea set up was **very very respectful of us**… they **double marked him practically for large parts of the game**」(첼시의 셋업은 우리를 매우 존중하는 것이었다… 경기의 상당 부분 **사실상 더블 마크**를 붙였다.) — auto-caption, **상대 감독**','HELD','⛔ **재판정 조건**: 상대 감독의 귀속이지 알론소 본인 진술이 아니다(피벗·백3 구성 질문은 회견에서 0건). ⇒ ⑴ 알론소가 백3 채택 사유를 진술하거나 ⑵ **상대 9번 유형이 다른 경기에서 백3/백4가 갈리는 2번째 표본**이 생기면 판정한다. 현재 실측 정황: 이 경기 첼시 PPDA **8.38**·def_x **41.0**으로 **높은 라인·강한 압박**이었다 — 「물러서서 존중」과는 다른 그림이라 앤드루스의 「respectful」은 **라인 높이가 아니라 대인 배치(더블마크)**를 가리키는 것으로 읽어야 한다. ⚠️ 두 축을 섞지 말 것.','reports/match-watch/2026-09-18-che-brentford.md D+2 절 · 전사 직접 독해 · WhoScored matchCentreData 1983573 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반(야넬트 건만 서면). 판정은 Opta 재집계와 대조했다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(152,'7J0YLBV25vc','limit',NULL,'CHE',NULL,NULL,'set_piece_target_switch','back_post_after_half_time','야넬트(브렌트포드) 원문 「**We did target [the back post] at half-time. There was a big gap**」(**우리는 하프타임에 뒤포스트를 노렸다. 큰 공간이 있었다**.) — Sky Sports 2026-09-19 서면','APPLIED','⭐⭐ **상대 선수가 첫 실점을 「하프타임에 특정한 표적」으로 자인했다** — 전반 앞포스트 2회 → 후반 뒤포스트 전환. 즉 실점은 우연이 아니라 **같은 루틴의 포스트 전환에 대응하지 못한 결손**이다. 알론소 본인도 같은 국면을 「우측 스로인–코너 연속」으로 묶어 규정했다. 정황 지지: 콜윌 자인(세트피스 5실점) · Opta 세트피스 누적 23실점(리그 공동 최악). ⇒ 게임 구현 함의는 **세트피스 수비 지시 축**이고, AVL 스퍼스전 claim #143(세트피스 마킹, HELD)과 **같은 부류**다 — 두 팀에서 같은 축이 동시에 열렸다. ⛔ 단일 경기라 팀 설정·슬롯 정본은 변경하지 않는다.','reports/match-watch/2026-09-18-che-brentford.md D+2 절 · 전사 직접 독해 · WhoScored matchCentreData 1983573 재집계(core.whoscored) 2026-09-20','MEDIUM — auto-caption 전사 기반(야넬트 건만 서면). 판정은 Opta 재집계와 대조했다.','2026-09-20');
