INSERT INTO video_impl_claims VALUES(158,'4iwS1CTVXr4','instruction',NULL,'CHE',NULL,NULL,'back_three_viability','needs_time_to_gel_else_back_four','원문 「**The back three system is very difficult. A lot of coaches have tried the system and they have failed.**… it is a system that is good **when your players understand it**」(**백3 시스템은 매우 어렵다. 많은 감독이 시도했고 실패했다.**… **선수들이 이해할 때** 좋은 시스템이다.) — auto-caption · 3티어','HELD','⛔ **재판정 조건**: 이 주장은 **시스템 적합성에 대한 일반론**이고 이 경기 실측으로 판정되지 않는다. 우리 실측이 말할 수 있는 것은 **이 경기 백3가 PPDA 8.38·def_x 41.0의 높은 압박과 함께 쓰였고 3실점했다**는 사실뿐이다(obs#892). ⇒ 판정하려면 **백3 ↔ 백4 경기 간 대조**가 필요하다: 알론소 체제에서 **백4로 선 경기 2경기 이상**이 쌓이면 def_x·PPDA·실점 패턴을 같은 축에서 비교한다. ⚠️ 층 구분: obs#893(상대 감독의 「치아구 더블마크」)은 **왜 골랐나**, 이 주장은 **왜 안 되나**다 — 둘은 경쟁 가설이 아니라 다른 질문이다. ⛔ 3티어 유튜버의 일반론이므로 단독으로 시즌 정본을 움직이지 않는다.','reports/match-watch/2026-09-18-che-brentford.md D+2 절(유튜브 직접 스윕 보충) · yt-dlp 2026-09-20','MEDIUM — auto-caption 전사. 3티어 채널 일반론은 단독으로 정본을 움직이지 않는다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(159,'XoqRKPT4D68','limit',NULL,'CHE',NULL,NULL,'back_three_not_auto_stability','space_behind_wingbacks','원문 「**Dreierkette bedeutet nicht automatisch defensive Sicherheit.**」(**백3가 자동으로 수비 안정을 뜻하지 않는다.**) · 「Die Dreierkette bekommt plötzlich **Probleme in Räumen, die eigentlich abgesichert sein sollten**」(백3가 **원래 보호돼야 할 공간에서** 문제를 겪는다.) — auto-caption, 🇩🇪','HELD','⛔ **재판정 조건**: 「보호돼야 할 공간」이 구체적으로 어디인지 영상이 좌표로 특정하지 않는다. ⇒ 우리 국면 그리드(이 경기 14명 신규 채움)로 **윙백 배후 구역의 상대 보유 셀 밀도**를 내고, 백4 경기와 대조되면 판정한다. ⭐ 현재 정황은 방향이 맞다: 첼시 def_x 41.0(높음)인데 3실점했고, 상대는 **역습 위협을 게임플랜으로 명시**했다(앤드루스 회견). ⚠️ 이 영상은 **시즌 3경기 아크**(7실점)를 다루므로 이 경기 단독 근거로 쓰면 과대 적용이다.','reports/match-watch/2026-09-18-che-brentford.md D+2 절(유튜브 직접 스윕 보충) · yt-dlp 2026-09-20','MEDIUM — auto-caption 전사. 3티어 채널 일반론은 단독으로 정본을 움직이지 않는다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(160,'TXjdbiTmcz0','none',NULL,'CHE',NULL,NULL,NULL,NULL,'구현 축 주장 없음 — 펀딧 평·재고 리뷰·프레이밍·의문 제기·리액션이다. 내용은 summary/key_points와 observations에 남겼다.','NA','axis=none. ⛔ 「산투스 영입」(iltNYp8lk6o)은 **사실 주장**이라 검증 전 구현 재료로 쓰지 않는다.','reports/match-watch/2026-09-18-che-brentford.md D+2 절(유튜브 직접 스윕 보충) · yt-dlp 2026-09-20','MEDIUM — auto-caption 전사. 3티어 채널 일반론은 단독으로 정본을 움직이지 않는다.','2026-09-20');
