INSERT INTO video_impl_claims VALUES(164,'FFl2vf7LpZs','none',NULL,'CHE',NULL,NULL,NULL,NULL,'구현 축 주장 없음 — 펀딧 평·재고 리뷰·프레이밍·의문 제기·리액션이다. 내용은 summary/key_points와 observations에 남겼다.','NA','axis=none. ⛔ 「산투스 영입」(iltNYp8lk6o)은 **사실 주장**이라 검증 전 구현 재료로 쓰지 않는다.','reports/match-watch/2026-09-18-che-brentford.md D+2 절(유튜브 직접 스윕 보충) · yt-dlp 2026-09-20','MEDIUM — auto-caption 전사. 3티어 채널 일반론은 단독으로 정본을 움직이지 않는다.','2026-09-20');
INSERT INTO video_impl_claims VALUES(165,'D7zbh9-q8d8','instruction',NULL,'AVL',NULL,NULL,'long_ball_target_zone','behind_advanced_fullbacks','원문 「if their fullbacks come forward, there''s space behind their fullbacks … a lot of that was by design」(그들의 풀백이 전진하면 그 뒤에 공간이 생긴다 … 상당 부분이 설계된 것이었다)','APPLIED','실측이 지지한다. Opta(pulled 2026-09-21 scope=full): 스즈키 롱볼 27회(성공 10) · 골킥 7회 전부 롱 · 이 경기 롱볼 비중 14.5%는 26/27 최고(obs#864). 에메리 본인이 「롱볼은 설계」를 1차 진술했고(obs#882) 상대 감독이 경기 전 정량 스카우팅으로 독립 확인했다(claim #140). ⛔ 시즌 정본 team_tactic_setups(Short Passing)는 바꾸지 않는다 — 에메리의 빌드업은 상대 의존이고 헐전 롱볼 5.6%가 같은 시즌에 있다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(166,'D7zbh9-q8d8','instruction',NULL,'AVL',NULL,NULL,'long_ball_pin_effect','pins_opposition_fullbacks','원문 「it made sure that Archie Gray had to stay back. It made sure that Andy Robertson had to stay back」(아치 그레이가 뒤에 남아야 했고 앤디 로버트슨도 뒤에 남아야 했다)','APPLIED',unistr('⛔ 실측이 부분적으로만 지지한다. 토트넘 풀백의 전진 빈도를 보유 이벤트로 대리 측정하면 로버트슨(LB)은 전반 n=29 → 후반 n=51로 **오히려 76% 늘었고** y도 75.1→80.8로 더 벌어졌다 — 후반에는 억제되지 않았다. 그레이는 전반 n=20 → 후반 n=21로 불변. ⇒ 「묶어뒀다」는 전반 한정 서술일 수 있으나 채널은 구간을 특정하지 않았다. ⛔ 재판정 조건: 전반/후반을 나눈 상대 풀백 전진 지표(터치 x 평균·파이널서드 진입 수)를 롱볼 시도 직후 60초 창으로 좁혀 산출한다. 그 창에서 풀백 x가 유의하게 낮으면 APPLIED.\u000a[D+3 2026-09-21 재계산 — APPLIED] WhoScored matchId 1983589 재수집(1627건) 후 조건대로 ''롱볼 시도 직후 60초 창'' vs ''창 밖''으로 토트넘 풀백(포로/그레이 RB · 로버트슨 LB) x 위치를 분리했다. AVL 롱볼 54회. 창밖 x̄=60.2(n=82) → 창안 x̄=49.7(n=92), Δ10.5, Welch t=2.98(양쪽 합산). 개별로도 로버트슨 창밖 65.1→창안 52.3(Δ12.7, t=3.11)로 유의, 포로/그레이는 55.6→45.0(Δ10.6, t=1.80·경계선). ⇒ 조건 충족(유의하게 낮음) — 이전 D+2의 반박(로버트슨 전반/후반 이벤트 수 29→51 증가)은 ''전진 빈도''를 재는 잘못된 지표였다 — 이벤트 수가 늘어도 그 순간의 위치가 눌려있으면 억제는 유지된다. obs#938.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(167,'D7zbh9-q8d8','instruction',NULL,'AVL',NULL,NULL,'pivot_partnership_ball_dominance','kamara_gomes_neither_dominant','원문 「Neither of them want to be massively ball dominant」(둘 다 볼을 크게 지배하려 하지 않는다)','PENDING',unistr('이 경기 실측: 카마라 패스 42(성공 35)·터치 48 · 주앙 고메스 패스·터치는 비슷한 대역이고 어느 쪽도 팀 배급을 독점하지 않는다. 다만 「지배하려 하지 않는다」는 성향 주장이라 단일 경기로 판정하지 않는다. ⛔ 재판정 조건: 두 선수 동시 선발 3경기에서 팀 패스 점유율 상위 1·2위를 CB가 차지하는 패턴이 반복되면 APPLIED.\u000a[D+3 2026-09-21 — 조건 미충족, PENDING 유지] 카마라·고메스 동시 선발 공식전은 이번 경기까지 4경기(08-12 슈퍼컵·08-23 PL·09-08 UCL·09-19 PL)이지만 08-23은 stats_json 결손으로 패스 집계 불가. 패스량 랭킹: 08-12 슈퍼컵(부엔디아1·캐시2·린델뢰프3, 카마라8·고메스9 — CB 상위 아님) / 09-08 UCL(파우 토레스1·린델뢰프2 — **CB 듀오가 상위 1·2위**, 카마라3·고메스5) / 09-19 이 경기(밍스1·카마라2 — CB 1명만 상위, 고메스는 순위 밖). ⇒ 「CB가 1·2위」 패턴은 3경기 중 1경기(09-08)에서만 나타나 **반복 조건 미충족**. PENDING 유지.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(168,'-5lhUwdm9QU','instruction',NULL,'AVL',NULL,NULL,'defensive_shape_second_half','back_five_to_back_six','원문 「dropping into that back five, dropping into that back six when we needed to」(필요할 때 백5로, 백6으로 내려앉았다)','APPLIED','실측이 지지한다 — 맥긴 수비액션 x 전반 56.3 → 후반 32.1, 우측 풀백 33.1(완비사카) → 17.2(캐시). 후반 점유 29% · def_x 30.6(26/27 최저). claim #138·#150과 같은 방향이고 상대팀 채널이 독립 서술했다. ⭐ 단 obs(D+2)에서 이 형태가 **토트넘의 하프타임 측면 전환에 대한 응답**임이 상대측 실측으로 밝혀졌다 — 기본 설계가 아니라 조건부 조정으로 한정한다. ⛔ 시즌 정본 포메이션·라인 축은 바꾸지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(169,'-5lhUwdm9QU','instruction',NULL,'AVL',NULL,NULL,'deep_block_runner_tracking','mcginn_fails_to_track_runners','원문 「McGinn again, he''s got to start tracking these runners — they ran off him」(맥긴은 다시, 러너를 추적하기 시작해야 한다 — 그를 등지고 뛰어 들어갔다)','HELD',unistr('⛔ 우리 이벤트 데이터는 **추적 실패**(상대 침투를 놓친 장면)를 담지 않는다 — 수비액션은 개입한 것만 기록되고 개입하지 못한 것은 결손으로 남는다. 정황: 맥긴은 후반 수비액션 8건으로 우측 최저 깊이(x 32.1)까지 내려갔으나 그 구간에 토트넘의 빌라 우측 침투가 39→84로 늘었다. ⛔ 재판정 조건: ⑴ 실점·빅찬스 시퀀스에서 맥긴이 마크를 놓친 장면이 독립 2소스로 특정되거나 ⑵ 같은 지적이 2경기째 누적되면 판정한다.\u000a[D+3 2026-09-21 — 조건 미충족, HELD 유지] 독립 2소스 검색 재시도(영어 「McGinn tracking runners Tottenham Aston Villa deep block」) — 신규 0건, 기존 하이라이트·리포트 재인용뿐. 같은 지적의 2경기째 누적도 없다(video_impl_claims에 field=''deep_block_runner_tracking'' 행이 이 1건뿐). 조건 그대로 유지.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(170,'-9ar6UOF958','instruction',NULL,'AVL',NULL,NULL,'rb_rotation_criterion','wanbissaka_defence_cash_possession','원문 「he''s better than Ezri Konsa. He''s not going to be as good as Matty Cash, certainly in possession」(콘사보다는 낫다. 소유 국면에서는 캐시만큼은 안 될 것이다)','APPLIED','기용 사실이 이 서열을 집행했다 — 완비사카 선발(45분) → 캐시 HT 투입(45분). Townley는 빌라 전담 1티어이고 D+1에 확보한 그의 평점 기사와 같은 진단이다(obs#867·#872·#880). ⇒ FC 구현: 우측 풀백 슬롯은 **국면 의존 로테이션**이고, 완비사카는 수비 지시(Defend/Balanced)·캐시는 전진 지시(Support/Attack) 쪽 근거가 된다. ⛔ 단일 경기이므로 슬롯 정본은 바꾸지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(171,'dgEOoi6Pdrc','instruction',NULL,'AVL',NULL,NULL,'away_vs_top_game_plan','defend_deep_then_transition','원문 「the manager was expecting at minimum nil-nil at halftime」(감독은 하프타임에 최소한 0-0을 기대하고 있었다)','APPLIED','claim #137의 **3번째 독립 확인**이다 — 에메리 본인(「keeping the result with nil nil was our process to try to grow up during the match」/0-0으로 결과를 유지하는 것이 경기 중 성장하려는 우리의 프로세스였다) · 맥긴(이 전언) · 실측(def_x 30.6 · PPDA 13.24 · 전반 점유 43%). 시즌 정본은 바꾸지 않는다(단일 경기).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(172,'dgEOoi6Pdrc','instruction',NULL,'AVL',NULL,NULL,'set_piece_defending_marking','mark_drop_under_flight_fail','원문 「a pretty simple straight set piece that just cleared the head of Tyrone Mings」(밍스의 머리를 넘긴 아주 단순한 세트피스)','APPLIED','⭐ claim #143이 건 재판정 조건(**독립 2번째 소스**)이 충족됐고 실측이 메커니즘을 확인한다. Opta 97′28 반헤케 골 quals = **Head + BoxCentre + SetPiece + FirstTouch**, 어시스트는 로버트슨의 **Cross + FreekickTaken**(프리킥이지 코너가 아니다). ⇒ 「세트피스 크로스가 박스 중앙에서 공중 경합을 이기고 헤더로 마무리됐다」까지 확정된다. ⛔ 잔여 한계: **개인 마킹 배치**(누가 누구를 놓쳤는가)는 우리 이벤트 데이터로 여전히 특정되지 않는다 — 「밍스의 머리를 넘었다」는 영상 서술 1소스에 의존한다. 이 해상도까지만 APPLIED로 닫는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(173,'kV4Mha-L0aA','instruction',NULL,'AVL',NULL,NULL,'gk_long_kick_route','goal_kick_to_ten_flick_to_nine','원문 「実際今日の我々の2点目でもそれをやってくれた」(실제로 오늘 우리 두 번째 골에서도 그것을 해줬다) — 에메리','APPLIED','⭐⭐ claim #141을 **Opta 이벤트로 확증**한다. 66′08 스즈키 Pass(qualifiers: **Longball + GoalKick**, x4.9) → 잭슨 BallTouch(x67.2) → 만잠비 Pass(**IntentionalGoalAssist + KeyPass**) → 잭슨 TakeOn 성공(반더벤 Challenge 실패) → 66′16 잭슨 Goal(Volley, BoxCentre). ⇒ 「골킥 → 9번 플릭 → 10번 → 9번 마무리」 경로가 이벤트 단위로 복원된다. 감독 본인이 이 연결을 진술했고(일본어 경유) 일본 매체 FOOTBALL ZONE이 같은 시퀀스를 독립 서술했다. ⭐ 이것은 스즈키의 골킥 7회가 전부 롱이었다는 실측(obs · claim #144)과 같은 그림이다 — GK는 빌드업 참여자가 아니라 **득점으로 전환되는 발사대**다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(174,'v6cVSXOaS8E','instruction',NULL,'AVL',NULL,NULL,'away_vs_top_game_plan','defend_deep_then_transition','원문 「Villa''s perfect willingness to sit in, congest, and then play long over us」(빌라의, 내려앉아 밀집하고 우리 머리 위로 길게 넘기려는 완벽한 의지)','APPLIED','⭐ **상대 코치 시각의 독립 확인**이다(claim #137 보강). 우리 실측(def_x 30.6 · PPDA 13.24 · 후반 점유 29% · 롱볼 14.5%)과 상대 감독의 사전 스카우팅(claim #140)과 같은 방향이다. 제3자·적대적 소스가 같은 구조를 서술했다는 점이 추가 정보다. 시즌 정본은 바꾸지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(175,'QkA0fScs5s8','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Counter','원문 「this season Aston Villa are playing 86% more long balls than last season」(이번 시즌 빌라는 지난 시즌보다 롱볼을 86% 더 많이 찬다) — 데 제르비','APPLIED','claim #140과 같은 주장이고 이 소스가 **auto-caption 의존을 해소하는 더 긴 맥락**을 준다(회견 전문 11분). ⚠️ 단 「86%」는 토트넘 내부 스카우팅 수치이고 **Opta 공표값이 아니다** — 「Opta에 따르면」은 허위 귀속이다(obs#875). ⚠️ 이 수치를 인용한 매체가 여럿이지만 **전부 같은 데 제르비 회견이 원천**이라 교차검증이 아니라 동일 원천의 중복이다(불변규칙 12). ⛔ 시즌 정본 team_tactic_setups(Short Passing)는 바꾸지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(176,'QkA0fScs5s8','instruction',NULL,'AVL',NULL,NULL,'lead_management_after_three_nil','switch_off_concede_two','원문 「Villa had kind of switched off by then anyway. It wasn''t us playing well that got us those goals」(그때쯤 빌라는 이미 스위치를 껐다. 우리가 잘해서 넣은 골이 아니다)','REJECTED',unistr('⛔ 「집중이 풀렸다」는 심리 귀속이라 이벤트로 직접 판정되지 않는다. 실측 정황은 양방향이다 — 지지: 86′·97′ 두 실점이 3-0 이후 11분 안에 나왔고 obs#865(87′~ 블록이 풀렸다)가 있다. 반대: 86′ 실점은 구조 붕괴가 아니라 **2차 처리 실패**로 이미 특정됐고(claim #142 APPLIED · Opta 시퀀스) 97′ 실점은 **세트피스**다 — 둘 다 「집중 이완」이 아니라 특정 국면의 실패다. ⇒ 대안 가설이 더 구체적이다. ⛔ 재판정 조건: 리드 3골 이후 구간의 PPDA·def_x를 별도 산출해 직전 구간 대비 유의하게 나빠지면 APPLIED, 아니면 REJECTED.\u000a[D+3 2026-09-21 재계산 — REJECTED(확정)] WhoScored matchId 1983589 이벤트를 79''(3-0 부엔디아골) 기준 분할. AVL PPDA 1H+2H초반(0-79'') 16.29(277/17) → 3-0 이후(79-98'') **6.40**(64/10) — 더 낮다(더 압박적). def_x 29.3(n=131) → **36.3**(n=35) — 더 높다(라인이 더 전진). 방향이 ''이완'' 가설과 **정반대**다. ⇒ REJECTED 확정. 대안 가설(claim #142 2차 처리 실패·#143 세트피스, 둘 다 APPLIED)이 여전히 더 구체적이다. obs#939.'),'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(177,'U4OewDAQMCk','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-21','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-21');
INSERT INTO video_impl_claims VALUES(178,'k6dbBj7Tz7w','instruction',NULL,'AVL',NULL,NULL,'pivot_drop_purpose','defensive_completion_not_buildup','질문 「second half you went into really a back five on the edge of your penalty area, McGinn went back and played really deep…」(후반에 사실상 페널티 박스 끝단에서 백5로 갔고 맥긴이 내려가 아주 깊게 뛰었다) / 에메리 「Yeah, **sometimes with back four is not enough to defend completely** … **the first half we use it more Kamara dropping, dropping, and someday is a five, center back being in the back four inside, and the second half we needed more with John McGinn.**」(그렇다. **때로는 백4로는 완전히 수비하기에 충분하지 않다** … **전반에는 카마라를 더 많이 내려, 내려 썼고, 어떤 때는 5가 된다 — 센터백이 백4 안쪽에 들어가는 식으로. 그리고 후반에는 존 맥긴으로 그걸 더 해줄 필요가 있었다.**)','APPLIED','⭐⭐ **축 정정의 근거다 — 감독 본인이 카마라의 하강을 「빌드업」이 아니라 「수비 완결성」 목적으로 규정한다.** 질문도 답도 **수비 국면**(백5·박스 끝단·맥긴 하강)에 관한 것이고, 에메리는 「백4로는 완전히 수비하기에 충분하지 않다」를 이유로 든다. ⇒ claim #139(`buildup_back_three_source`)가 **REJECTED된 이유가 여기서 설명된다 — 행동은 실재하나 축이 틀렸다.** 빌드업 국면 한정 실측이 Δ=10.6으로 임계를 넘지 못한 것은 이 행동이 빌드업 목적이 아니었기 때문으로 읽는 것이 정합적이다(obs#920). ⭐ 전·후반 분업도 실측과 합치한다: **전반=카마라 / 후반=맥긴**이라는 에메리의 구분이 맥긴 수비액션 x 전반 56.3 → 후반 32.1(−24.2)과 정확히 같은 방향이다. ⛔ **단 「카마라가 CB 라인 깊이까지 내려갔다」는 실측되지 않는다** — 전반 수비액션 x 카마라 38.6 vs CB라인 19.4(Δ 19.3, n=9). ⇒ APPLIED는 **「전반 하강의 목적이 수비이고 후반에 맥긴이 그 역할을 이어받았다」**까지이고, **깊이·형태(백3/백5)는 포함하지 않는다.** ⚠️ 한계: 우리 데이터는 온더볼·수비액션 지점만 담고 **터치 없는 위치 점유**는 담지 않는다 — 형태 주장은 트래킹 데이터 없이는 닫히지 않는다. ⛔ 시즌 정본 포메이션·슬롯은 바꾸지 않는다(단일 경기).','전사 원문 읽기 · D+2 추적(2026-09-21) 영상 스윕','auto-caption 전사 기반(인용은 원문+한국어 번역 병기) — 인물명·수치는 실측 교차검증했다','2026-09-21');
INSERT INTO video_impl_claims VALUES(179,'o_K-WGntCx4','instruction',NULL,'ATM',NULL,NULL,'attack_target_side','right_flank_by_design','「buscando dónde le podíamos hacer daño, que sabíamos que era por la derecha」(「어디서 상대에게 피해를 줄 수 있을지 찾았고, 그게 오른쪽이라는 걸 알고 있었다」)','PENDING','감독 1차 발언 + 실측 정합(이강인 tool_x 74.7·줄리아노 82.9·요렌테 77.6, PK·2골 모두 우측)이지만 단일 경기다. 재판정 조건: 퇴장 없는 라리가 2경기에서 우측 3인(이강인·줄리아노·우측 풀백) 평균 tool_x 합이 좌측 3인을 계속 상회하면 manager_profiles in_possession 축에 반영한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 감독 1차 발언 · 원문+번역 병기','2026-09-23');
INSERT INTO video_impl_claims VALUES(180,'o_K-WGntCx4','instruction',NULL,'ATM',NULL,NULL,'second_half_danger_conceded','cuti_llorente_miscommunication_to_diomande','「en el segundo tiempo, solo en el fallo ese entre el Cuti Marco que se chocan para Diamandés… fue la única situación de peligro que atravesó el equipo más el gol」(「후반에는 쿠티와 마르코가 충돌해 디오망데에게 간 그 실수 하나뿐이었다… 골 말고는 팀이 겪은 유일한 위험 장면이었다」)','PENDING','실측 대조 완료 — 후반 레알 오픈플레이 슛은 77′ 디오망데(xG 0.0706·xGOT 0.0194·세이브) 1건뿐이라 장면 특정은 성립한다. 다만 「쿠티-요렌테 충돌」이라는 원인은 좌표 이벤트로 확인 불가(터치·충돌 로그 없음) — 영상 확인이 필요해 PENDING.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 + 실측(match_shots) 대조','2026-09-23');
INSERT INTO video_impl_claims VALUES(181,'o_K-WGntCx4','instruction',NULL,'ATM',NULL,NULL,'koke_bench_rationale','impact_example_not_starting_shift','「Lo vieron a Coke 30 y pico de años y no juega de titular el partido de su vida… entra en el segundo tiempo y la rompe toda」(「코케를 봐라, 서른 몇 살에 인생의 경기에 선발로 못 나서고… 후반에 들어와 다 부숴버린다」)','PENDING','리포트 §7 재검증 ⑶(코케 선발 논의)에 대한 1차 답 — 감독은 선발 전환을 시사하지 않았고 교체 임팩트를 팀 문화 사례로 썼다. 재판정 조건: 다음 라리가 2경기 중 1회라도 코케가 선발이면 이 판정을 정정한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 감독 1차 발언','2026-09-23');
INSERT INTO video_impl_claims VALUES(182,'DK2dlVF3dFo','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','무리뉴 회견 구간에 ATM 구현 주장 0건(심판 논쟁이 회견 전체를 지배). 같은 영상 45:51~의 시메오네 구간 주장은 o_K-WGntCx4(동일 회견 단독 영상)에 기록했다 — 중복 적재하지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 감독 1차 발언','2026-09-23');
INSERT INTO video_impl_claims VALUES(183,'OKqnpw4YZyQ','team_axis',NULL,'ATM',NULL,NULL,'formation','5-3-2 (비보유) ↔ 4-4-2 (보유)','「optó por los tres centrales con Hanko, Cuti Romero y Mark Pubil, más dos carrileros… Además lo hacía en un 532」 / 「Tanto Grimaldo y Mar Pubil justamente actuaban como laterales」(「3센터백에 두 윙백… 5-3-2로 했다」 / 「그리말도와 푸빌이 (보유 시) 풀백처럼 움직였다」)','PENDING','우리 실측과 정면으로 판정할 수 없다 — 국면 그리드의 **비보유 표본이 푸빌 n=3**이라 백3 여부를 가릴 수 없다(ATM 점유 61%). 방향 단서는 엇갈린다: 비보유 전진값(0=최후방)이 CB 0.69~0.92인데 그리말도 1.89(n=9)·줄리아노 1.62(n=21)로 **한 행 앞**이라 플랫 백5보다 백4 미드블록에 가깝다. 재판정 조건: 다음 ATM 경기에서 우측 풀백의 비보유 셀 n≥15를 확보해 CB 라인과 같은 행에 서는지 본다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 실측 국면 그리드 표본 부족으로 미결','2026-09-23');
INSERT INTO video_impl_claims VALUES(184,'OKqnpw4YZyQ','role',162,'ATM','st_false9','Attack',NULL,NULL,'「Kangli que también caía a banda desde la posición de delantero centro」(「이강인도 최전방 위치에서 측면으로 빠졌다」)','PENDING','리포트 §7 재검증 ⑴(이강인 RST 슬롯 의심)에 대한 서사 측 답 — 슬롯은 명목상 투톱이 맞고 **측면으로 빠지는 것이 설계된 우측 과부하의 일부**라는 설명이다. 시메오네 본인 발언(「sabíamos que era por la derecha」)·실측 tool_x 74.7과 3중 수렴하지만 prescriptions는 이번에도 바꾸지 않는다(Δ0.046 실측 무결정). 재판정 조건: 다음 경기에서도 tool_x>70이면 슬롯 표기를 RST 유지 + role_note에 우측 과부하를 명기한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 + 감독 발언 + 실측 3중 수렴','2026-09-23');
INSERT INTO video_impl_claims VALUES(185,'OKqnpw4YZyQ','role',159,'ATM','fb_wingback','Support',NULL,NULL,'「Marcos Llorente volvió a ser ese lateral derecho. Cuando el Atlético no tenía el balón, Marcos Llorente se posicionaba como tercer central」(「요렌테가 다시 우측 풀백이 됐다. 공이 없을 때는 세 번째 센터백으로 섰다」)','PENDING','실측 하프 분할(1H x̄ 56.4·ȳ 28.7 → 2H 44.1·17.7)과 방향 일치하지만, 이 경기 처방은 전반 RCM 표본이 섞여 단일 행으로 확정할 수 없다(리포트 §5 한계 ②). 재판정 조건: 요렌테가 90분 전부 우측 풀백으로 뛴 경기가 나오면 그때 fb_* 축으로 확정한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 + 실측 하프 분할 정합','2026-09-23');
INSERT INTO video_impl_claims VALUES(186,'OKqnpw4YZyQ','instruction',NULL,'ATM',NULL,NULL,'right_side_overload','four_v_one_on_opposition_left_back','「hasta cuatro jugadores por este sector del Atlético Madrid para un solo lateral」(「이 구역에 아틀레티코 선수가 최대 4명, 상대는 풀백 한 명」)','PENDING','감독 발언(우측 표적)과 같은 메커니즘을 선수 배치로 설명한 것 — 근거는 영상 화면이고 우리 좌표로는 「우편중」까지만 확인된다(동시성·수적 우위는 미검증). 재판정 조건: 패스 네트워크 또는 구간 좌표를 재수집해 우측 3~4인 동시 진입 빈도를 세면 확정 가능.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 실측은 방향만 지지','2026-09-23');
INSERT INTO video_impl_claims VALUES(187,'OKqnpw4YZyQ','instruction',NULL,'ATM',NULL,NULL,'koke_bench_rationale','first_half_needs_recovering_midfielders','「Pedía situar a tres centrocampistas más guerreros, Johnny, Marcos Llorente, Alex Baena… A Coke esto le cuesta un poquito más」(「더 전사 같은 미드필더 3인, 조니·요렌테·바에나를 놓아야 했다… 코케는 그게 좀 더 힘들다」)','PENDING','시메오네 본인 발언(교체 임팩트 예시)과 독립적으로 같은 결론(선발 전환 아님)에 도달했다 — 리포트 §7 ⑶은 이로써 「현 시점 선발 전환 근거 없음」으로 닫는다. 재판정 조건: 코케가 다음 2경기 중 선발하면 정정.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 감독 발언과 독립 수렴','2026-09-23');
INSERT INTO video_impl_claims VALUES(188,'ckLOOWC6t80','team_axis',NULL,'ATM',NULL,NULL,'formation','백3(푸빌 센터백) — 독립 2차 소스','「jugó Mar Pubil de centrales, Cuti Romero y Hanko… Simeone en medio de carrilero llegando de extremo」(「푸빌이 센터백으로, 쿠티 로메로와 한츠코… 시메오네는 윙어처럼 올라가는 윙백으로」)','PENDING','OKqnpw4YZyQ와 독립적으로 같은 형태를 읽었다(채널·국가·관점 상이). ⚠️ 그러나 **동일 중계 화면을 본 두 해설이므로 완전한 독립 교차검증은 아니다**(불변규칙 12 주의 지점). 우리 실측(푸빌 tool_x 83.7 — 백3 RCB로는 지나치게 넓다)과는 여전히 어긋나며, 판정은 OKqnpw4YZyQ 항목과 동일한 재판정 조건에 묶는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 실측 tool_x와 불일치 — 미결','2026-09-23');
INSERT INTO video_impl_claims VALUES(189,'VO1_wJHgbI0','instruction',NULL,'ATM',NULL,NULL,'first_half_tempo_control','fouls_to_deny_opposition_transitions','「ciertamente más físico, metió, creo que fueron 10 faltas en la primera parte y empezaba a tomar el control」(「더 피지컬하게, 전반에 10개의 파울을 범하며 통제를 쥐기 시작했다」)','PENDING','실측과 숫자까지 일치한다(1H 파울 10:3·경기 19:6). 다만 「의도된 전술」이라는 해석은 해설자 판단이고 감독 발언으로 뒷받침되지 않았다 — 시메오네는 파울을 언급하지 않았다. 재판정 조건: 라리가 3경기 누적 1H 파울이 상대의 2배 이상으로 반복되면 manager_profiles defence 축에 「템포 차단 파울」을 정식 등재한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 실측 정합 · 의도 귀속은 미검증','2026-09-23');
INSERT INTO video_impl_claims VALUES(190,'VO1_wJHgbI0','instruction',NULL,'ATM',NULL,NULL,'opposition_winger_containment','force_wide_not_press_pivot','「la idea del Cholo Simeone, más que pendiente de Tchouaméni y Valverde, era de que jugasen banda Güler y Vinicius」(「촐로의 아이디어는 추아메니·발베르데를 신경 쓰기보다 귈러와 비니시우스를 측면에서 뛰게 만드는 것이었다」)','PENDING','실측 PPDA 1H 12.46(중블록)·def_x 38.3(상대보다 낮음)과 방향이 맞는다 — 중앙을 막고 측면으로 밀었다는 서술. 단 상대 윙어의 터치 분포를 우리가 수집하지 않아 직접 확인은 불가. 재판정 조건: 상대 윙어 터치의 측면 비율을 수집하는 축을 docs/60 양식으로 사전등록한 뒤 판정한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능) · 실측은 방향만 지지','2026-09-23');
INSERT INTO video_impl_claims VALUES(191,'09a0RHhf2hg','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','ATM 구현 주장 0건 — 판정 논쟁·상대팀 개인 비판만. 「미작성」이 아니라 「주장 없음」임을 남긴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능)','2026-09-23');
INSERT INTO video_impl_claims VALUES(192,'OpljifSJc_I','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','ATM 구현 주장 0건 — 상대팀 관점 판정 논쟁 중심. 「미작성」이 아니라 「주장 없음」임을 남긴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사(오인식 가능)','2026-09-23');
INSERT INTO video_impl_claims VALUES(193,'BcaSff9xn9w','focus',72,NULL,NULL,'Build-Up',NULL,NULL,'「at the end he has to help us to to be closer to the box to play in a position half to have meaningful possession」(「결국 그는 우리가 박스 가까이 가도록, 더 높은 위치에서 의미 있는 점유를 하도록 도와야 한다.」)','HELD','이 경기 처방(st_false9/Build-Up, fit 0.695, Δ0.032 실측 무결정)의 1위를 감독 진술이 지지한다 — 값을 바꾸지 않았으므로 APPLIED가 아니라 HELD다. 재판정 조건: 이삭이 같은 pos_class로 2경기를 더 채운 뒤 재산출했을 때 Attack이 Build-Up을 Δ>0.05로 앞서면 뒤집는다. ⚠️ auto-caption — 「in a position half」는 「in a position higher」의 오인식으로 읽었고, 그 해석에 의존하지 않는 부분(「closer to the box」·「meaningful possession」)만 근거로 썼다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-23');
INSERT INTO video_impl_claims VALUES(194,'BcaSff9xn9w','team_axis',NULL,'LIV',NULL,NULL,'line_height','리드·피압박 국면에서 내려서는 것을 감독이 용인한다(단일 낮은 값 아님)','「in moments now that you need to defend our side or they are putting you pressure I think we are we are looking solid」(「이제 우리 진영을 지켜야 하거나 상대가 압박을 거는 국면에서 우리는 단단해 보인다.」)','HELD','match_game_setups(report 49) line_height 58을 바꾸지 않는다. 이 진술은 하프별 PPDA 반전(8.46→14.60)이 사고가 아님을 지지하지만 「평시 라인을 낮게 설정한다」는 주장은 아니다 — 게임 설정은 국면 전환을 담지 못한다(docs/30 「평균 위치는 국면을 평균해 지운다」와 같은 한계). 재판정 조건: 리드 전후를 분리한 PPDA가 2경기 더 같은 방향으로 반전되면 line_height를 국면 처방(리드 후 하강)으로 분리 기술한다. ⚠️ auto-caption.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-23');
INSERT INTO video_impl_claims VALUES(195,'JAK1M-_PTyw','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-23','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-23');
